import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"User Feedback Survey","description":"","frontmatter":{},"headers":[],"relativePath":"project/user-feedback-survey.md","filePath":"project/user-feedback-survey.md"}'),s={name:"project/user-feedback-survey.md"};function i(r,e,l,c,p,h){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="user-feedback-survey" tabindex="-1">User Feedback Survey <a class="header-anchor" href="#user-feedback-survey" aria-label="Permalink to &quot;User Feedback Survey&quot;">​</a></h1><p><strong>Version</strong>: 1.0 · For use in: pilot interviews (5–10 participants) <strong>Format</strong>: 10 questions, ~8 minutes to complete. Can be run as a live interview or sent as a written form (Typeform / Google Forms). <strong>Target</strong>: freelancers, diaspora senders, or SME finance leads who send money internationally.</p><hr><h2 id="screening-confirm-before-starting" tabindex="-1">Screening (confirm before starting) <a class="header-anchor" href="#screening-confirm-before-starting" aria-label="Permalink to &quot;Screening (confirm before starting)&quot;">​</a></h2><blockquote><p>&quot;In the last 12 months, have you sent money from Europe or North America to someone in Nigeria, India, or Brazil — either as a personal remittance or as a business payment to a contractor?&quot;</p></blockquote><ul><li>Yes → continue</li><li>No → thank them and close</li></ul><hr><h2 id="section-a-—-pain-points-unprompted" tabindex="-1">Section A — Pain points (unprompted) <a class="header-anchor" href="#section-a-—-pain-points-unprompted" aria-label="Permalink to &quot;Section A — Pain points (unprompted)&quot;">​</a></h2><p><strong>Q1.</strong> When you last sent money abroad, what bothered you most about the process? <em>(open-ended, max 2 minutes — let them speak before asking follow-ups)</em></p><blockquote><p>Probe if not mentioned: speed / cost / hidden fees / knowing the money arrived / having to explain what service to use to the recipient?</p></blockquote><hr><p><strong>Q2.</strong> On a scale of 1–5, how confident were you that the compliance checks (identity verification, source of funds) were actually done correctly?</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 — Not confident at all</span></span>
<span class="line"><span>2 — Slightly confident</span></span>
<span class="line"><span>3 — Neutral / didn&#39;t think about it</span></span>
<span class="line"><span>4 — Fairly confident</span></span>
<span class="line"><span>5 — Completely confident</span></span></code></pre></div><p><em>If 1–3:</em> &quot;What would have made you more confident?&quot;</p><hr><h2 id="section-b-—-concept-reaction" tabindex="-1">Section B — Concept reaction <a class="header-anchor" href="#section-b-—-concept-reaction" aria-label="Permalink to &quot;Section B — Concept reaction&quot;">​</a></h2><p><em>Read this aloud (or display it verbatim):</em></p><blockquote><p>&quot;Imagine a service where you pay by card in euros. A licensed financial partner converts the money to a regulated stablecoin, which settles to the recipient&#39;s bank account in seconds — they receive local currency, nothing crypto. At no point does either of you need a crypto wallet or know what a blockchain is. And every compliance check in the process is cryptographically timestamped on a public ledger, so a regulator — or you — can verify the checks actually happened, without relying on the company&#39;s own records.&quot;</p></blockquote><hr><p><strong>Q3.</strong> What is your immediate reaction to this? <em>(open-ended)</em></p><hr><p><strong>Q4.</strong> On a scale of 1–5, how likely would you be to try this for your next international transfer?</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 — Very unlikely</span></span>
<span class="line"><span>2 — Unlikely</span></span>
<span class="line"><span>3 — Neutral</span></span>
<span class="line"><span>4 — Likely</span></span>
<span class="line"><span>5 — Very likely</span></span></code></pre></div><p><em>If 1–3:</em> &quot;What would need to change for you to try it?&quot;</p><hr><p><strong>Q5.</strong> What concerns, if any, do you have about this service?</p><p><em>(Prompt if silent: cost? safety of funds? whether it&#39;s legal? whether the recipient can access the money?)</em></p><hr><h2 id="section-c-—-value-proposition-sharpening" tabindex="-1">Section C — Value proposition sharpening <a class="header-anchor" href="#section-c-—-value-proposition-sharpening" aria-label="Permalink to &quot;Section C — Value proposition sharpening&quot;">​</a></h2><p><strong>Q6.</strong> The fact that compliance checks are verifiable on a public ledger — how valuable is that to you personally?</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 — Not valuable (I don&#39;t care about the audit trail)</span></span>
<span class="line"><span>2 — Slightly valuable</span></span>
<span class="line"><span>3 — Neutral / I hadn&#39;t thought about it</span></span>
<span class="line"><span>4 — Valuable — I&#39;d feel more secure using the service</span></span>
<span class="line"><span>5 — Very valuable — this is a meaningful reason to choose this over alternatives</span></span></code></pre></div><p><em>If 4–5:</em> &quot;Can you say more about why?&quot; <em>(The answer here is your strongest marketing message.)</em><em>If 1–2:</em> &quot;What would make you feel secure about the service instead?&quot; <em>(note verbatim)</em></p><hr><p><strong>Q7.</strong> What would you expect to pay in total fees for sending €500 to Nigeria / India / Brazil? <em>(accept their current expectation unprompted)</em></p><blockquote><p>Interviewer note: this calibrates pricing tolerance. Compare against your current fee model (flat fee + stated FX spread).</p></blockquote><hr><h2 id="section-d-—-trust-channels" tabindex="-1">Section D — Trust &amp; channels <a class="header-anchor" href="#section-d-—-trust-channels" aria-label="Permalink to &quot;Section D — Trust &amp; channels&quot;">​</a></h2><p><strong>Q8.</strong> How did you find your current money-transfer service? <em>(tick all that apply)</em></p><ul><li>[ ] Recommendation from a friend or family member</li><li>[ ] Community group (WhatsApp, forum, diaspora association)</li><li>[ ] Comparison website (MoneySuperMarket, Monito, etc.)</li><li>[ ] Social media / influencer</li><li>[ ] Bank recommendation</li><li>[ ] Just searched online</li><li>[ ] Other: ___________</li></ul><blockquote><p>Interviewer note: dominant channel = first acquisition channel to invest in.</p></blockquote><hr><p><strong>Q9.</strong> If you learned that a new service was officially partnered with a local mobile money provider in the recipient&#39;s country (e.g. MTN MoMo in Nigeria, or Airtel Money in India), how much more likely would that make you to try it?</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 — No difference</span></span>
<span class="line"><span>2 — Slightly more likely</span></span>
<span class="line"><span>3 — Moderately more likely</span></span>
<span class="line"><span>4 — Much more likely</span></span>
<span class="line"><span>5 — That would be a key reason to switch</span></span></code></pre></div><hr><h2 id="section-e-—-open-close" tabindex="-1">Section E — Open close <a class="header-anchor" href="#section-e-—-open-close" aria-label="Permalink to &quot;Section E — Open close&quot;">​</a></h2><p><strong>Q10.</strong> Is there anything else about sending money abroad that really frustrates you — that you wish someone would solve?</p><p><em>(Take verbatim notes. This is often where the most useful insight lives.)</em></p><hr><h2 id="interviewer-debrief-not-shown-to-participant" tabindex="-1">Interviewer debrief (not shown to participant) <a class="header-anchor" href="#interviewer-debrief-not-shown-to-participant" aria-label="Permalink to &quot;Interviewer debrief (not shown to participant)&quot;">​</a></h2><p>After each session, rate these three signals:</p><table tabindex="0"><thead><tr><th>Signal</th><th>Your assessment (1–5)</th></tr></thead><tbody><tr><td>Pain intensity: how viscerally did they describe the problem?</td><td></td></tr><tr><td>Concept pull: did they ask questions, or just answer?</td><td></td></tr><tr><td>Willingness to pay: did their stated fee expectation match or exceed our model?</td><td></td></tr></tbody></table><p><strong>Threshold to proceed</strong>: if ≥ 6 of 10 participants score 4–5 on Q4, the core concept is validated. If Q6 scores consistently below 3, deprioritise the compliance-trail angle in consumer messaging and lead with speed + fee transparency instead.</p><hr><h2 id="how-to-document-results-for-the-submission" tabindex="-1">How to document results for the submission <a class="header-anchor" href="#how-to-document-results-for-the-submission" aria-label="Permalink to &quot;How to document results for the submission&quot;">​</a></h2><ol><li>Anonymise all participants (P1–P10, country, occupation only).</li><li>Record Q3, Q5, Q10 verbatim — quotes are evidence.</li><li>Tabulate Q4 and Q6 scores as a distribution.</li><li>Write a 2-paragraph summary: what the top pain point was, and whether participants valued the verifiable compliance trail or needed a different angle.</li><li>Commit the summary to <code>docs/analysis/testing-validation.md</code> under a new &quot;External Validation&quot; heading.</li></ol>`,55)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
